    }

    public void start() {
        ticking = true;
        startTick = ticks;
    }

    public void tick() {
        ticks++;
    }

    public boolean isExpired() {
        if (!ticking) {
            return false;
        }
        return (ticks - startTick) >= durationTicks;
    }

